import csv
import re
from collections import defaultdict
from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Sale:
    day: date
    product: str
    quantity: int
    cents: int


PRICE = re.compile(r"(\d+)(?:\.(\d{1,2}))?")


def read_sales(lines):
    reader = csv.reader(lines)
    header = next(reader, None)
    if header is None or [h.strip().lower() for h in header] != ["date", "product", "quantity", "unit_price"]:
        return [], ["bad header"]
    sales, errors = [], []
    for number, row in enumerate(reader, start=1):
        if len(row) != 4:
            errors.append(f"row {number}: wrong number of fields")
            continue
        day_text, product, qty_text, price_text = (f.strip() for f in row)
        try:
            day = date.fromisoformat(day_text)
        except ValueError:
            errors.append(f"row {number}: bad date {day_text}")
            continue
        if not product:
            errors.append(f"row {number}: missing product")
            continue
        if not qty_text.isdigit() or int(qty_text) == 0:
            errors.append(f"row {number}: bad quantity {qty_text}")
            continue
        m = PRICE.fullmatch(price_text)
        if not m:
            errors.append(f"row {number}: bad price {price_text}")
            continue
        cents = int(m.group(1)) * 100 + int((m.group(2) or "0").ljust(2, "0"))
        sales.append(Sale(day, product, int(qty_text), cents))
    return sales, errors


def in_range(sales, start, end):
    return [s for s in sales if (start is None or s.day >= start) and (end is None or s.day <= end)]


def by_month(sales):
    months = defaultdict(lambda: [0, 0])
    for s in sales:
        entry = months[s.day.strftime("%Y-%m")]
        entry[0] += 1
        entry[1] += s.quantity * s.cents
    return {m: (orders, rev) for m, (orders, rev) in sorted(months.items())}


def top_products(sales, n):
    totals = defaultdict(int)
    for s in sales:
        totals[s.product] += s.quantity * s.cents
    return sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))[:n]


def money(cents):
    sign = "-" if cents < 0 else ""
    whole, rest = divmod(abs(cents), 100)
    return f"{sign}{whole:,}".replace(",", " ") + f".{rest:02}"


def format_report(sales, errors, n):
    lines = [f"Sales: {len(sales)} rows, {len(errors)} rejected", f"{'Month':<7}{'Orders':>10}{'Revenue':>14}"]
    for month, (orders, rev) in by_month(sales).items():
        lines.append(f"{month:<7}{orders:>10}{money(rev):>14}")
    lines.append("Top products")
    for i, (product, rev) in enumerate(top_products(sales, n), start=1):
        lines.append(f"  {i}. {product:<12}{money(rev):>12}")
    if errors:
        lines.append("Errors")
        lines.extend(f"  {e}" for e in errors)
    return "\n".join(lines) + "\n"
